cd thumbs/sb && python3 << 'EOF'
import json, subprocess, os, concurrent.futures as cf

meta = json.load(open('meta.json'))
jobs = []
for L, m in meta.items():
    for i, url in enumerate(m['urls']):
        f = '%s_%02d.jpg' % (L, i)
        jobs.append((url, f))

def dl(job):
    url, f = job
    if os.path.exists(f) and os.path.getsize(f) > 3000:
        return f, 'cached'
    for attempt in range(4):
        r = subprocess.run(['curl','-s','-o',f,url], capture_output=True)
        if os.path.exists(f) and os.path.getsize(f) > 3000:
            return f, 'ok'
    return f, 'FAIL'

with cf.ThreadPoolExecutor(16) as ex:
    res = list(ex.map(dl, jobs))
fails = [r for r in res if r[1]=='FAIL']
print('downloaded: %d, failed: %d' % (sum(1 for r in res if r[1]!='FAIL'), len(fails)))
if fails: print(fails[:10])
EOF

